document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".godam-video-preview .easydam-video-container");if(0===e.length)return;const t=[];e.forEach(e=>{const o=e.querySelector("video");if(!o)return;const n=o.id;let d=null;if(n&&window.videojs)try{d=window.videojs.getPlayer(n)}catch(e){}const i=()=>{const t=o.videoWidth,n=o.videoHeight;if(!t||!n)return;if(d){const e=`${t}:${n}`;d.aspectRatio(e)}const i=e.closest(".godam-video-preview");if(!i)return;const r=Math.round(t/n*450),a=i.offsetWidth,s=Math.min(a,768),c=Math.min(r,s);e.style.width=`${c}px`,e.style.maxHeight="450px"};o.readyState>=1?i():o.addEventListener("loadedmetadata",i),t.push(i),window.addEventListener("resize",i)}),window.addEventListener("beforeunload",()=>{t.forEach(e=>{window.removeEventListener("resize",e)})})});